{"command": "cat > /tmp/count.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
)

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, os.Args[1], nil, 0)
	if err != nil {
		fmt.Println("parse err:", err)
		return
	}
	count := 0
	ast.Inspect(f, func(n ast.Node) bool {
		if n != nil {
			count++
			fmt.Printf("%T\n", n)
		}
		return true
	})
	fmt.Println("total nodes:", count)
}
EOF
go run /tmp/count.go /tmp/sens/min.go
echo "==="
go run /tmp/count.go /tmp/t3/a.go
"}

