var (
	filesFlag    bool
	htmlFlag     bool
	plumbingFlag bool
	threshold    int
	vendorFlag   bool
	verboseFlag  bool
)

func init() {
	flag.BoolVar(&filesFlag, "files", false, "read file names from stdin one at each line")
	flag.BoolVar(&htmlFlag, "html", false, "output the results as HTML, including duplicate code fragments")
	flag.BoolVar(&plumbingFlag, "plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
