type posInfo struct {
	filename  string
	line      int
	column    int
	offset    int
	endLine   int
	endCol    int
	endOffset int
}

type cloneLoc struct {
	file      string
	startLine int
	endLine   int
	startOff  int
	endOff    int
}

type cloneGroup struct {
	clones []cloneLoc
	size   int
}

func isVendor(path string) bool {
	slash := filepath.ToSlash(path)
	parts := strings.Split(slash, "/")
	for _, p := range parts {
		if p == "vendor" {
			return true
		}
	}
	return false
}

