	"sort"
	"strings"
)

var (
	filesFlag    bool
	htmlFlag     bool
	plumbingFlag bool
	threshold    int
	vendorFlag   bool
	verboseFlag  bool
)

func init() {
	flag.BoolVar(&filesFlag, "files", false, "read file names from stdin one at each line")
	flag.BoolVar(&htmlFlag, "html", false, "output the results as HTML, including duplicate code fragments")
	flag.BoolVar(&plumbingFlag, "plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flag.IntVar(&threshold, "t", 15, "minimum token sequence size as a clone")
	flag.IntVar(&threshold, "threshold", 15, "minimum token sequence size as a clone")
	flag.BoolVar(&vendorFlag, "vendor", false, "check files in vendor directory")
	flag.BoolVar(&verboseFlag, "v", false, "explain what is being done")
	flag.BoolVar(&verboseFlag, "verbose", false, "explain what is being done")
	flag.Usage = func() {
		fmt.Fprint(os.Stderr, "Usage: dupl [flags] [paths]\n\nPaths:\n  If the given path is a file, dupl will use it regardless of\n  the file extension. If it is a directory, it will recursively\n  search for *.go files in that directory.\n\n  If no path is given, dupl will recursively search for *.go\n  files in the current directory.\n\nFlags:\n  -files\n    \tread file names from stdin one at each line\n  -html\n    \toutput the results as HTML, including duplicate code fragments\n  -plumbing\n    \tplumbing (easy-to-parse) output for consumption by scripts or tools\n  -t, -threshold size\n    \tminimum token sequence size as a clone (default 15)\n  -vendor\n    \tcheck files in vendor directory\n  -v, -verbose\n    \texplain what is being done\n\nExamples:\n  dupl -t 100\n    \tSearch clones in the current directory of size at least\n    \t100 tokens.\n  dupl $(find app/ -name '*_test.go')\n    \tSearch for clones in tests in the app directory.\n  find app/ -name '*_test.go' |dupl -files\n    \tThe same as above.\n")
	}
}

type posInfo struct {
	filename  string
	line      int
	column    int
	offset    int
	endLine   int
	endCol    int
	endOffset int
}

type cloneLoc struct {
	file      string
	startLine int
	endLine   int
	startOff  int
	endOff    int
}

type cloneGroup struct {
	clones []cloneLoc
	size   int
}

func isVendor(path string) bool {
	slash := filepath.ToSlash(path)
	parts := strings.Split(slash, "/")
	for _, p := range parts {
		if p == "vendor" {
			return true
		}
	}
	return false
}

func main() {
	flag.Parse()
	th := threshold
	if th < 1 {
		th = 1
	}
	fset := token.NewFileSet()

