	seenSuccess := make(map[string]bool)

	if filesFlag {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			orig := scanner.Text()
			cleaned := orig
			if strings.HasPrefix(cleaned, "./") {
				cleaned = cleaned[2:]
			}
			if seenSuccess[cleaned] {
				continue
			}
			f, err := parser.ParseFile(fset, cleaned, nil, 0)
