					if err != nil {
						return nil
					}
					if info.IsDir() {
						return nil
					}
					if !strings.HasSuffix(path, ".go") {
						return nil
					}
					if !vendorFlag && isVendor(path) {
						return nil
					}
					if seenSuccess[path] {
						return nil
					}
					f, perr := parser.ParseFile(fset, path, nil, 0)
					if perr != nil {
						log.Println(perr)
						return nil
					}
					content, cerr := os.ReadFile(path)
					if cerr != nil {
						log.Println(cerr)
						return nil
					}
					seenSuccess[path] = true
