		infos = append(infos, posInfo{filename: "", line: -1})
	}
	if len(tokens) > 0 {
		tokens = tokens[:len(tokens)-1]
		infos = infos[:len(infos)-1]
	}
	n := len(tokens)
	var groups []cloneGroup
	if n > 0 && len(parsedFiles) > 0 {
		sa := make([]int, n)
		for i := range sa {
			sa[i] = i
		}
		sort.Slice(sa, func(i, j int) bool {
			a, b := sa[i], sa[j]
			for a < n && b < n {
				if tokens[a] != tokens[b] {
					return tokens[a] < tokens[b]
				}
				a++
				b++
			}
			if a == n && b == n {
				return false
			}
			if a == n {
				return true
			}
			return false
		})
		lcp := make([]int, n)
		for i := 1; i < n; i++ {
			a, b := sa[i], sa[i-1]
			l := 0
			for a+l < n && b+l < n && tokens[a+l] == tokens[b+l] {
				l++
			}
			lcp[i] = l
		}
		type interval struct {
			l, r, min int
		}
		var intervals []interval
		for l := 0; l < n; l++ {
			minV := 1 << 30
			for r := l + 1; r < n; r++ {
				if lcp[r] < minV {
					minV = lcp[r]
				}
				if minV < th {
					break
				}
				leftOk := (l == 0) || (lcp[l] < minV)
				rightOk := (r == n-1) || (lcp[r+1] < minV)
				if leftOk && rightOk {
					intervals = append(intervals, interval{l, r, minV})
				}
			}
		}
		seenGroups := make(map[string]int)
		for _, iv := range intervals {
			var poss []int
			for k := iv.l; k <= iv.r; k++ {
				pos := sa[k]
				if infos[pos].filename == "" {
					continue
				}
				poss = append(poss, pos)
			}
			if len(poss) < 2 {
				continue
			}
			containsSep := false
			for _, p := range poss {
				for k := 0; k < iv.min; k++ {
					if p+k >= n || infos[p+k].filename == "" {
						containsSep = true
						break
					}
				}
				if containsSep {
					break
				}
			}
			if containsSep {
				continue
			}
			var clones []cloneLoc
			for _, p := range poss {
				startInfo := infos[p]
				maxEndLine := startInfo.endLine
				maxEndOff := startInfo.endOffset
				for k := 0; k < iv.min; k++ {
					inf := infos[p+k]
					if inf.endOffset > maxEndOff {
						maxEndOff = inf.endOffset
						maxEndLine = inf.endLine
					} else if inf.endOffset == maxEndOff {
						if inf.endLine > maxEndLine {
							maxEndLine = inf.endLine
						}
					}
				}
				clones = append(clones, cloneLoc{file: startInfo.filename, startLine: startInfo.line, endLine: maxEndLine, startOff: startInfo.offset, endOff: maxEndOff})
			}
			sort.Slice(clones, func(i, j int) bool {
				if clones[i].file != clones[j].file {
					return clones[i].file < clones[j].file
				}
				if clones[i].startLine != clones[j].startLine {
					return clones[i].startLine < clones[j].startLine
				}
				return clones[i].endLine < clones[j].endLine
			})
			var keyBuilder strings.Builder
			for _, c := range clones {
				keyBuilder.WriteString(c.file)
				keyBuilder.WriteString(":")
				keyBuilder.WriteString(fmt.Sprint(c.startLine))
				keyBuilder.WriteString(",")
				keyBuilder.WriteString(fmt.Sprint(c.endLine))
				keyBuilder.WriteString(";")
			}
			keyStr := keyBuilder.String()
			if _, ok := seenGroups[keyStr]; ok {
				continue
			}
			seenGroups[keyStr] = len(groups)
			groups = append(groups, cloneGroup{clones: clones, size: iv.min})
		}
		sort.Slice(groups, func(i, j int) bool {
			if groups[i].size != groups[j].size {
				return groups[i].size > groups[j].size
			}
			a, b := groups[i].clones[0], groups[j].clones[0]
			if a.file != b.file {
				return a.file < b.file
			}
			if a.startLine != b.startLine {
				return a.startLine < b.startLine
			}
			return len(groups[i].clones) > len(groups[j].clones)
		})
	}
	contentMap := make(map[string][]byte)
	for _, pf := range parsedFiles {
		contentMap[pf.filename] = pf.content
	}
	if htmlFlag {
		fmt.Print("<!DOCTYPE html>\n<meta charset=\"utf-8\"/>\n<title>Duplicates</title>\n<style>\n\tpre {\n\t\tbackground-color: #FFD;\n\t\tborder: 1px solid #E2E2E2;\n\t\tpadding: 1ex;\n\t}\n</style>\n")
		for i, g := range groups {
			fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(g.clones))
