				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", c.file, c.startLine, c.endLine, next.file, next.startLine, next.endLine)
			}
		}
	} else {
		for _, g := range groups {
			fmt.Printf("found %d clones:\n", len(g.clones))
			for _, c := range g.clones {
				fmt.Printf("  %s:%d,%d\n", c.file, c.startLine, c.endLine)
			}
		}
		if len(groups) == 0 {
			fmt.Printf("\nFound total 0 clone groups.\n")
		} else {
			fmt.Printf("\nFound total %d clone groups.\n", len(groups))
		}
	}
}

func extractFragment(filename string, startOff, endOff int, contentMap map[string][]byte) string {
	data, ok := contentMap[filename]
	if !ok {
		return ""
	}
	var lineStarts []int
	lineStarts = append(lineStarts, 0)
	for i, b := range data {
		if b == '\n' {
			if i+1 < len(data) {
				lineStarts = append(lineStarts, i+1)
			} else {
				lineStarts = append(lineStarts, i+1)
			}
		}
	}
	findLine := func(off int) int {
		line := 1
		for i := 0; i < off && i < len(data); i++ {
			if data[i] == '\n' {
				line++
			}
		}
		return line
	}
	sLine := findLine(startOff)
	eLine := sLine
	if endOff > startOff {
		eLine = findLine(endOff - 1)
		if eLine < sLine {
			eLine = sLine
		}
	} else {
		eLine = sLine
	}
	lineStartOff := 0
	if sLine-1 < len(lineStarts) {
		lineStartOff = lineStarts[sLine-1]
	}
	var prefixBytes []byte
	if lineStartOff <= startOff && startOff <= len(data) {
		prefixBytes = data[lineStartOff:startOff]
	}
	isAllTabs := len(prefixBytes) > 0
	if isAllTabs {
		for _, b := range prefixBytes {
			if b != '\t' {
				isAllTabs = false
				break
			}
		}
	}
	var tokenSlice []byte
	if startOff <= endOff && endOff <= len(data) && startOff <= len(data) {
		tokenSlice = data[startOff:endOff]
	}
	s := string(tokenSlice)
	tlines := strings.Split(s, "\n")
	var fragLines []string
	if isAllTabs {
		fragLines = make([]string, len(tlines))
		fragLines[0] = tlines[0]
		for i := 1; i < len(tlines); i++ {
			str := tlines[i]
			j := 0
			for j < len(str) && str[j] == '\t' {
				j++
			}
			fragLines[i] = str[j:]
		}
	} else {
		newPrefix := make([]byte, len(prefixBytes))
		for i, b := range prefixBytes {
			if b == '\t' || b == ' ' {
				newPrefix[i] = b
			} else {
				newPrefix[i] = ' '
			}
		}
		fragLines = make([]string, len(tlines))
		fragLines[0] = string(newPrefix) + tlines[0]
		for i := 1; i < len(tlines); i++ {
			fragLines[i] = tlines[i]
		}
	}
	_ = eLine
	return strings.Join(fragLines, "\n")
}
