		filename string
		astFile  *ast.File
		content  []byte
	}
	var parsedFiles []fileData
	seenSuccess := make(map[string]bool)
	if filesFlag {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			orig := scanner.Text()
			cleaned := orig
			if strings.HasPrefix(cleaned, "./") {
				cleaned = cleaned[2:]
			}
			if seenSuccess[cleaned] {
				continue
			}
			f, err := parser.ParseFile(fset, cleaned, nil, 0)
			if err != nil {
				log.Println(err)
				continue
			}
			content, err := os.ReadFile(cleaned)
			if err != nil {
				log.Println(err)
				continue
			}
