					}
					content, cerr := os.ReadFile(path)
					if cerr != nil {
						log.Println(cerr)
						return nil
					}
					seenSuccess[path] = true
					parsedFiles = append(parsedFiles, fileData{filename: path, astFile: f, content: content})
					return nil
				})
			} else {
				if seenSuccess[arg] {
					continue
				}
				f, perr := parser.ParseFile(fset, arg, nil, 0)
				if perr != nil {
					log.Println(perr)
					continue
				}
				content, cerr := os.ReadFile(arg)
				if cerr != nil {
					log.Println(cerr)
					continue
				}
				seenSuccess[arg] = true
				parsedFiles = append(parsedFiles, fileData{filename: arg, astFile: f, content: content})
			}
		}
	}
	if verboseFlag {
		log.Println("Searching for clones")
	}
	sort.Slice(parsedFiles, func(i, j int) bool { return parsedFiles[i].filename < parsedFiles[j].filename })
	var tokens []int
	var infos []posInfo
	typeMap := make(map[string]int)
	nextVal := 1
	getVal := func(typeName string) int {
		if v, ok := typeMap[typeName]; ok {
			return v
		}
		v := nextVal
		nextVal++
		typeMap[typeName] = v
		return v
	}
	for _, pf := range parsedFiles {
		fpos := fset.Position(pf.astFile.Pos())
		fend := fset.Position(pf.astFile.End())
		v := getVal("*ast.File")
		tokens = append(tokens, v)
		infos = append(infos, posInfo{filename: pf.filename, line: fpos.Line, column: fpos.Column, offset: fpos.Offset, endLine: fend.Line, endCol: fend.Column, endOffset: fend.Offset})
		for _, decl := range pf.astFile.Decls {
			ast.Inspect(decl, func(n ast.Node) bool {
				if n == nil {
					return true
				}
				tn := fmt.Sprintf("%T", n)
				val := getVal(tn)
				p := fset.Position(n.Pos())
				e := fset.Position(n.End())
				tokens = append(tokens, val)
				infos = append(infos, posInfo{filename: pf.filename, line: p.Line, column: p.Column, offset: p.Offset, endLine: e.Line, endCol: e.Column, endOffset: e.Offset})
				return true
			})
		}
		tokens = append(tokens, -len(tokens)-1000000)
		infos = append(infos, posInfo{filename: "", line: -1})
	}
	if len(tokens) > 0 {
		tokens = tokens[:len(tokens)-1]
		infos = infos[:len(infos)-1]
	}
	n := len(tokens)
	var groups []cloneGroup
	if n > 0 && len(parsedFiles) > 0 {
		sa := make([]int, n)
		for i := range sa {
			sa[i] = i
		}
		sort.Slice(sa, func(i, j int) bool {
			a, b := sa[i], sa[j]
			for a < n && b < n {
				if tokens[a] != tokens[b] {
					return tokens[a] < tokens[b]
				}
				a++
				b++
			}
			if a == n && b == n {
