				if clones[i].file != clones[j].file {
					return clones[i].file < clones[j].file
				}
				if clones[i].startLine != clones[j].startLine {
					return clones[i].startLine < clones[j].startLine
				}
				return clones[i].endLine < clones[j].endLine
			})
			var keyBuilder strings.Builder
			for _, c := range clones {
				keyBuilder.WriteString(c.file)
				keyBuilder.WriteString(":")
				keyBuilder.WriteString(fmt.Sprint(c.startLine))
				keyBuilder.WriteString(",")
				keyBuilder.WriteString(fmt.Sprint(c.endLine))
				keyBuilder.WriteString(";")
			}
			keyStr := keyBuilder.String()
			if _, ok := seenGroups[keyStr]; ok {
