{"command": "cat > /tmp/dump.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func main() {
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "/tmp/order.go", nil, 0)
	typeMap := map[string]int{}
	next := 1
	get := func(s string) int {
		if v, ok := typeMap[s]; ok { return v }
		v := next; next++; typeMap[s]=v; return v
	}
	var toks []int
	var infos []string
	toks = append(toks, get("*ast.File"))
	infos = append(infos, "File")
	for _, d := range f.Decls {
		ast.Inspect(d, func(n ast.Node) bool {
			if n==nil { return true }
			t := fmt.Sprintf("%T", n)
			toks = append(toks, get(t))
			p:=fset.Position(n.Pos())
			infos = append(infos, fmt.Sprintf("%s:%d", t, p.Line))
			return true
		})
	}
	fmt.Println("tokens:", toks[:100])
	fmt.Println("infos:", infos[:20])
	fmt.Println("total", len(toks))
	// Find small funcs tokens? Small funcs are first 2 decls (small1, small2), big are next 2 (big1,big2)? Actually order.go has small1,small2,big1,big2? No, order.go has small1,small2,big1,big2? Actually order.go has small1 (lines3-8), small2 (10-15), big1 (17-30), big2 (32-45)? Good. So first 2 decls small, next 2 big.
	// Count tokens per decl? Need to compute subtree sizes for each FuncDecl
	for i, d := range f.Decls {
		c:=0
		ast.Inspect(d, func(n ast.Node) bool { if n!=nil {c++}; return true })
		fmt.Printf("decl %d (%T) size %d\n", i, d, c)
	}
}
EOF
GO111MODULE=off go build -o /tmp/dumpbin /tmp/dump.go && /tmp/dumpbin 2>&1 | head -n 30
"}

